import com.bridger.momentum.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public final class ClipStreamRegression {
    private static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception{
        if(!NativeClipTools.windows()){System.out.println("SKIP: native rolling buffer requires Windows x64");return;}
        Path root=Files.createTempDirectory("bridgetap-stream-test-");int w=320,h=180,fps=args.length==0?60:Integer.parseInt(args[0]),count=fps*30+fps/5;byte[] pattern=new byte[w*h*3];new Random(8).nextBytes(pattern);
        for(int y=0;y<h;y++)for(int x=0;x<64;x++){int p=(y*w+x)*3;if(y<40){pattern[p]=(byte)240;pattern[p+1]=0;pattern[p+2]=0;}else if(y>=h-40){pattern[p]=0;pattern[p+1]=0;pattern[p+2]=(byte)240;}}
        try(ClipStreamBuffer stream=new ClipStreamBuffer(root)){
            stream.reset(1,30);long base=System.nanoTime(),wall=System.nanoTime();
            for(int i=0;i<count;i++){byte[] rgb;while((rgb=ClipRgbPool.acquire(pattern.length))==null)Thread.sleep(1);System.arraycopy(pattern,0,rgb,0,pattern.length);rgb[(h/2*w+w/2)*3]=(byte)i;for(int bit=0;bit<12;bit++)for(int yy=h/2+16;yy<h/2+24;yy++)for(int xx=64+bit*8;xx<72+bit*8;xx++){int pixel=(yy*w+xx)*3;byte shade=(byte)(((i>>bit)&1)==0?0:240);rgb[pixel]=rgb[pixel+1]=rgb[pixel+2]=shade;}for(int y=h-32;y<h;y++)for(int x=w-64;x<w;x++){int p=(y*w+x)*3;rgb[p]=(byte)(i<count-5?240:0);rgb[p+1]=(byte)(i>=count-5?240:0);rgb[p+2]=0;}while(!stream.offer(1,base+Math.round(i*1e9/fps),rgb,w,h,w,h,fps)){if(!stream.error().isEmpty()){ClipRgbPool.release(rgb);throw new AssertionError(stream.error());}Thread.sleep(1);}}
            try(ClipStreamBuffer.Snapshot saved=stream.snapshot(base+Math.round(count*1e9/fps)).get(25,TimeUnit.SECONDS)){
                check(saved.duration()>=29.9&&saved.duration()<31,"Ring did not preserve the requested 30 seconds plus keyframe padding: "+saved.duration());check((long)pattern.length*count>ClipFrames.MAX_BYTES,"Regression must exceed the old raw-image memory limit");
                Path target=root.resolve("thirty-seconds.mp4");saved.write(target,null);check(Files.size(target)>1000,"Rolling stream export is empty");
                Path wave=root.resolve("tone.wav");try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(wave))){int samples=48000;out.writeBytes("RIFF");little(out,36+samples*2,4);out.writeBytes("WAVEfmt ");little(out,16,4);little(out,1,2);little(out,1,2);little(out,48000,4);little(out,96000,4);little(out,2,2);little(out,16,2);out.writeBytes("data");little(out,samples*2,4);for(int i=0;i<samples;i++)little(out,(int)(Math.sin(i*2*Math.PI*440/48000)*12000),2);}
                Path withAudio=root.resolve("with-audio.mp4");saved.write(withAudio,wave);Process audio=new ProcessBuilder(NativeClipTools.tool("ffmpeg.exe").toString(),"-v","error","-i",withAudio.toString(),"-map","0:a:0","-frames:a","10","-f","s16le","-").redirectError(root.resolve("audio-error.txt").toFile()).start();ByteArrayOutputStream pcm=new ByteArrayOutputStream();byte[] soundChunk=new byte[8192];try(InputStream in=audio.getInputStream()){int n;while((n=in.read(soundChunk))>=0)pcm.write(soundChunk,0,n);}check(audio.waitFor()==0&&pcm.size()>10000,"Rolling export lost its AAC audio track");long energy=0;byte[] samples=pcm.toByteArray();for(int i=0;i+1<samples.length;i+=2){short value=(short)((samples[i]&255)|(samples[i+1]<<8));energy+=(long)value*value;}check(energy/(samples.length/2)>1000000,"Rolling export audio contains silence");
                Path progress=root.resolve("decode-progress.txt");Process decode=new ProcessBuilder(NativeClipTools.tool("ffmpeg.exe").toString(),"-v","error","-i",target.toString(),"-map","0:v:0","-progress","pipe:1","-f","null","-").redirectError(root.resolve("decode-error.txt").toFile()).redirectOutput(progress.toFile()).start();check(decode.waitFor(30,TimeUnit.SECONDS)&&decode.exitValue()==0,"Rolling MP4 does not decode");
                int frames=0;long micros=0;for(String line:Files.readAllLines(progress)){if(line.startsWith("frame="))frames=Integer.parseInt(line.substring(6).trim());if(line.startsWith("out_time_us="))micros=Long.parseLong(line.substring(12).trim());}
                check(frames>=fps*30&&frames<fps*31&&micros>=30000000L&&micros<31000000L,"Incorrect real MP4 rate/duration: "+frames+" frames, "+micros+" us");
                Path hashes=root.resolve("frame-hashes.txt");Process identities=new ProcessBuilder(NativeClipTools.tool("ffmpeg.exe").toString(),"-v","error","-i",target.toString(),"-frames:v",String.valueOf(fps),"-f","framemd5","-").redirectError(root.resolve("hash-error.txt").toFile()).redirectOutput(hashes.toFile()).start();check(identities.waitFor(30,TimeUnit.SECONDS)&&identities.exitValue()==0,"Frame identities could not be decoded");Set<String> unique=new HashSet<>();for(String line:Files.readAllLines(hashes))if(!line.startsWith("#")&&line.contains(","))unique.add(line.substring(line.lastIndexOf(',')+1).trim());check(unique.size()>=fps-2,"Frame rate contains duplicated images instead of distinct captures: "+unique.size());
                Process ending=new ProcessBuilder(NativeClipTools.tool("ffmpeg.exe").toString(),"-v","error","-sseof","-0.04","-i",target.toString(),"-frames:v","1","-pix_fmt","rgb24","-f","rawvideo","-").redirectError(root.resolve("ending-error.txt").toFile()).start();ByteArrayOutputStream endingBytes=new ByteArrayOutputStream();byte[] tail=new byte[8192];try(InputStream in=ending.getInputStream()){int n;while((n=in.read(tail))>=0)endingBytes.write(tail,0,n);}check(ending.waitFor()==0&&endingBytes.size()==w*h*3,"Final frame is missing");byte[] lastFrame=endingBytes.toByteArray();int marker=(w-32)*3;check((lastFrame[marker+1]&255)>150&&(lastFrame[marker]&255)<80,"Saving trimmed off the most recent bridge moment");
                Process first=new ProcessBuilder(NativeClipTools.tool("ffmpeg.exe").toString(),"-v","error","-i",target.toString(),"-frames:v","1","-pix_fmt","rgb24","-f","rawvideo","-").redirectError(root.resolve("first-error.txt").toFile()).start();ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] chunk=new byte[8192];try(InputStream in=first.getInputStream()){int n;while((n=in.read(chunk))>=0)bytes.write(chunk,0,n);}check(first.waitFor()==0,"First frame decode failed");byte[] rgb=bytes.toByteArray();check(rgb.length==w*h*3&&(rgb[2]&255)>150&&(rgb[(h-1)*w*3]&255)>150,"Native raw RGB path lost vertical orientation or image colours");
                System.out.printf(Locale.US,"PASS: rolling 30-second / %d FPS clip, %d decoded frames; %s; %.1f seconds processing%n",fps,frames,stream.encoder(),(System.nanoTime()-wall)/1e9);
            }
            stream.reset(2,15);try{stream.snapshot(System.nanoTime()).get(15,TimeUnit.SECONDS);throw new AssertionError("Clear retained the previous video");}catch(ExecutionException expected){}
        }
    }
    private static void little(DataOutputStream out,int value,int count)throws IOException{for(int i=0;i<count;i++)out.writeByte(value>>(i*8));}
}
